I'll show you a debounced search input with a few approaches:

**React with hooks (custom debounce):**

```jsx
import { useState, useEffect, useRef } from 'react';

function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const debounceTimer = useRef(null);

  useEffect(() => {
    // Clear previous timer
    if (debounceTimer.current) {
      clearTimeout(debounceTimer.current);
    }

    // Set new timer
    debounceTimer.current = setTimeout(async () => {
      if (query.trim()) {
        setLoading(true);
        try {
          const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
          const data = await res.json();
          setResults(data);
        } catch (err) {
          console.error('Search failed:', err);
        } finally {
          setLoading(false);
        }
      } else {
        setResults([]);
      }
    }, 300); // 300ms delay

    // Cleanup
    return () => clearTimeout(debounceTimer.current);
  }, [query]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      {loading && <p>Loading...</p>}
      <ul>
        {results.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>
    </div>
  );
}
```

**Vanilla JavaScript version:**

```javascript
function createDebouncedSearch(apiUrl, delayMs = 300) {
  let debounceTimer;

  return function handleSearch(event) {
    const query = event.target.value;

    clearTimeout(debounceTimer);

    debounceTimer = setTimeout(async () => {
      if (query.trim()) {
        try {
          const res = await fetch(`${apiUrl}?q=${encodeURIComponent(query)}`);
          const data = await res.json();
          displayResults(data);
        } catch (err) {
          console.error('Search failed:', err);
        }
      }
    }, delayMs);
  };
}

// Usage
const searchInput = document.getElementById('search');
searchInput.addEventListener('input', createDebouncedSearch('/api/search', 300));
```

**Key changes:**
- **Delay before API call** — wrapped in `setTimeout` with 300ms debounce (adjust as needed)
- **Clear previous timer** — cancels pending calls when user types again
- **Skip empty searches** — checks `query.trim()` before calling API

Use **300-500ms** for most UX. Go longer (800-1000ms) for expensive queries or real-time results that feel jarring.
